(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["clinical-medicine-and-surgery-i-exam-3-external-middle-ear-quiz"]={"title":"External and Middle Ear Quiz 1 — CMS I Exam 3","category":"Clinical Medicine and Surgery I","exam":"Exam 3","sem":"fall-2026","questions":[{"q":"Which symptom pattern fits cerumen impaction?","choices":["Fever and severe throbbing pain","Vertigo and vomiting","Facial weakness","Bloody discharge","Itching, fullness and hearing loss"],"answer":4,"exp":"Correct — or it may be entirely asymptomatic. — Disorders External and Middle Ear 9-2026.pptx, Slide 28"},{"q":"What is the definitive treatment for cholesteatoma?","choices":["Long-term topical antibiotics","Observation with annual imaging","Tympanostomy tube placement","Systemic corticosteroids","Surgical removal"],"answer":4,"exp":"Correct, usually with tympanoplasty, after clearing debris and infection. — Disorders External and Middle Ear 9-2026.pptx, Slide 37"},{"q":"What does insufflation during otoscopy assess?","choices":["Mobility of the tympanic membrane","Colour of the tympanic membrane","Hearing threshold","Patency of the ear canal","Facial nerve function"],"answer":0,"exp":"Correct. A drum that will not move signals pressure or fluid behind it. — Disorders External and Middle Ear 9-2026.pptx, Slide 10"},{"q":"Which type of cholesteatoma is the commonest, and how does it form?","choices":["Primary, from retraction of the tympanic membrane","Secondary, from surgery","Congenital, present from birth","Traumatic, from a blow to the head","Infectious, from Pseudomonas"],"answer":0,"exp":"Correct, usually at the pars flaccida. — Disorders External and Middle Ear 9-2026.pptx, Slide 32"},{"q":"In which space does blood collect in an auricular haematoma?","choices":["The mastoid air cells","Beneath the tympanic membrane","The sub-perichondrial space","The middle ear","The external canal"],"answer":2,"exp":"Correct, which is what separates cartilage from its blood supply. — Disorders External and Middle Ear 9-2026.pptx, Slide 39"},{"q":"What is the correct advice for routine ear cleaning at home?","choices":["Irrigate monthly with a bulb syringe","Use a candle to draw wax out","Use a curette bought online","Use a washcloth over a finger at the opening","Use cotton swabs weekly"],"answer":3,"exp":"Correct — nothing enters the canal. — Disorders External and Middle Ear 9-2026.pptx, Slide 29"},{"q":"A patient with tympanostomy tubes needs wax removed. Who should do it?","choices":["The patient, using cotton swabs","A pharmacist with over-the-counter drops","Nobody — it should be left alone","An ear, nose and throat specialist","Any clinician using irrigation"],"answer":3,"exp":"Correct. Tubes and perforations both move removal to a specialist. — Disorders External and Middle Ear 9-2026.pptx, Slide 29"},{"q":"Which symptom most strongly suggests necrotizing external otitis rather than ordinary canal infection?","choices":["Itching that outlasts the pain","Discharge that settles with drops","Hearing that is better in noise","Fullness after a cold","Pain out of proportion to the examination findings"],"answer":4,"exp":"Correct. — Disorders External and Middle Ear 9-2026.pptx, Slide 61"},{"q":"What is the principal concern with an embedded earring?","choices":["Facial paralysis","Malignant transformation","Infection","Hearing loss","Vertigo"],"answer":2,"exp":"Correct — it outweighs concern about the object itself. — Disorders External and Middle Ear 9-2026.pptx, Slide 52"},{"q":"Which otoscopic appearance fits acute otitis media?","choices":["Dull with an air and fluid level","Normal in every respect","Blue-black from blood behind it","Erythematous and bulging","Retracted with normal colour"],"answer":3,"exp":"Correct, with reduced mobility on insufflation. — Disorders External and Middle Ear 9-2026.pptx, Slide 16"},{"q":"Which exposure is the leading risk factor for otitis externa?","choices":["Cold water diving","High altitude living","Moisture and swimming","Loud noise exposure","Air travel"],"answer":2,"exp":"Correct. — Disorders External and Middle Ear 9-2026.pptx, Slide 56"},{"q":"Which procedure addresses adenoid hypertrophy obstructing the eustachian tubes?","choices":["Tonsillectomy","Mastoidectomy","Myringoplasty","Stapedectomy","Adenoidectomy"],"answer":4,"exp":"Correct. — Disorders External and Middle Ear 9-2026.pptx, Slide 14"},{"q":"What proportion of people experience otitis externa in their lifetime?","choices":["Over ninety per cent","About ten per cent","About one per cent","About thirty per cent","About half"],"answer":1,"exp":"Correct. — Disorders External and Middle Ear 9-2026.pptx, Slide 54"},{"q":"A patient reports crackling and popping on swallowing after a cold. What does that finding indicate?","choices":["The inner ear is involved","The blockage is only partial","The blockage is complete","The tympanic membrane has ruptured","Infection has reached the mastoid"],"answer":1,"exp":"Correct. Sound moving at all means air is still passing intermittently. — Disorders External and Middle Ear 9-2026.pptx, Slide 8"},{"q":"Why do ear keloids require close follow-up after treatment?","choices":["They cause hearing loss","They spread to the other ear","They cause facial paralysis","Recurrence is common","They become malignant"],"answer":3,"exp":"Correct. — Disorders External and Middle Ear 9-2026.pptx, Slide 70"},{"q":"Which otoscopic finding indicates bleeding into the middle ear after barotrauma?","choices":["A chalky white mass","Haemotympanum","A retraction pocket","Fungal filaments","Canal exostoses"],"answer":1,"exp":"Correct — blood visible behind the drum. — Disorders External and Middle Ear 9-2026.pptx, Slide 23"},{"q":"Which otoscopic appearance is described as resembling wet newspaper?","choices":["Cerumen impaction","Cholesteatoma","Aspergillus infection","Candida infection","Pseudomonas infection"],"answer":2,"exp":"Correct — visible spores and filaments. — Disorders External and Middle Ear 9-2026.pptx, Slide 63"},{"q":"Which otoscopic finding fits otitis media with effusion?","choices":["A dull drum with an air and fluid level","A bright red bulging drum","A normal pearly grey drum","Keratin debris in a retraction pocket","Fungal filaments across the canal"],"answer":0,"exp":"Correct, with reduced mobility on insufflation. — Disorders External and Middle Ear 9-2026.pptx, Slide 13"},{"q":"Which instrument is used to remove a soft foreign body from the ear canal?","choices":["A right-angle hook","A wire loop","A bulb syringe","A curette","Alligator forceps"],"answer":4,"exp":"Correct; firm objects are taken with a loop or hook instead. — Disorders External and Middle Ear 9-2026.pptx, Slide 50"},{"q":"How is acute otitis media diagnosed?","choices":["By blood cultures","Clinically","By middle ear fluid culture","By computed tomography of the temporal bone","By audiometry"],"answer":1,"exp":"Correct. Tympanometry is optional and imaging has no routine role. — Disorders External and Middle Ear 9-2026.pptx, Slide 16"},{"q":"Roughly what share of acute otitis media diagnoses are made in adults?","choices":["Around fifty per cent","Over seventy per cent","Three to fifteen per cent","Under one per cent","Around thirty per cent"],"answer":2,"exp":"Correct. It is overwhelmingly a childhood disease. — Disorders External and Middle Ear 9-2026.pptx, Slide 12"},{"q":"What typically happens to the pain once a tympanic membrane ruptures?","choices":["It becomes a burning pain","It is replaced by vertigo in all cases","It stops","It becomes much worse","It moves to the opposite ear"],"answer":2,"exp":"Correct — the condition is generally not painful after rupture. — Disorders External and Middle Ear 9-2026.pptx, Slide 45"},{"q":"Which otoscopic finding indicates a cholesteatoma?","choices":["Keratin debris within a retraction pocket","A uniformly bulging red drum","An air and fluid level behind the drum","A completely normal drum","Bony growths in the canal wall"],"answer":0,"exp":"Correct, sometimes with visible erosion of the ossicles. — Disorders External and Middle Ear 9-2026.pptx, Slide 34"},{"q":"What colour is a normal tympanic membrane?","choices":["Pearly grey","Bright red","Chalky white","Deep blue","Bright yellow"],"answer":0,"exp":"Correct. Loss of that appearance is the first sign something lies behind it. — Disorders External and Middle Ear 9-2026.pptx, Slide 8"},{"q":"What is a cholesteatoma composed of?","choices":["Cholesterol crystals","Malignant epithelial cells","Inspissated cerumen","Granulation tissue only","Keratinised squamous epithelium"],"answer":4,"exp":"Correct. Despite the name it contains no cholesterol and is not a neoplasm. — Disorders External and Middle Ear 9-2026.pptx, Slide 31"},{"q":"Into how many clinical divisions is the ear separated?","choices":["Three","Two","Four","Five","Six"],"answer":0,"exp":"Correct. External, middle and inner. — Disorders External and Middle Ear 9-2026.pptx, Slide 4"},{"q":"What is the purpose of adding a corticosteroid to otic antibiotic drops?","choices":["To restore hearing directly","To reduce pain and inflammation","To broaden antibacterial cover","To dissolve cerumen","To prevent fungal overgrowth"],"answer":1,"exp":"Correct. — Disorders External and Middle Ear 9-2026.pptx, Slide 59"},{"q":"What is by far the commonest cause of acute otitis media overall?","choices":["Pseudomonas aeruginosa","A virus","Streptococcus pneumoniae","Haemophilus influenzae","Moraxella catarrhalis"],"answer":1,"exp":"Correct. Most episodes are viral, which is why most resolve without antibiotics. — Disorders External and Middle Ear 9-2026.pptx, Slide 17"},{"q":"What proportion of otosclerosis is bilateral and asymmetric?","choices":["About thirty per cent","About ninety-five per cent","All cases","About seventy per cent","About ten per cent"],"answer":3,"exp":"Correct; the remaining thirty per cent is unilateral. — Disorders External and Middle Ear 9-2026.pptx, Slide 65"},{"q":"Which perforations require surgical reconstruction?","choices":["Only those in children","Only bilateral ones","Only painful ones","Large ones, or ones present a long time","Every perforation, without exception"],"answer":3,"exp":"Correct. — Disorders External and Middle Ear 9-2026.pptx, Slide 47"}]};
